--!native
local WorldConfig = require(script.Parent:WaitForChild("WorldConfig"))

local MapSelect = require(script.Parent:WaitForChild("MapSelect"))

local v = {
	ironfield = { nx = 190, nz = 250, x0 = -380, z0 = -500 },
	sandline = { nx = 190, nz = 250, x0 = -380, z0 = -500 },
	saltpan = { nx = 248, nz = 266, x0 = -496, z0 = -532 },
	frostmill = { nx = 248, nz = 266, x0 = -496, z0 = -532 },
	pinewold = { nx = 280, nz = 280, x0 = -560, z0 = -560 },
	deepworks = { nx = 256, nz = 200, x0 = -512, z0 = -400 },
	drywell = { nx = 280, nz = 280, x0 = -560, z0 = -560 },
	highcrag = { nx = 280, nz = 280, x0 = -560, z0 = -560 },
	longreach = {
		nx = 360,
		nz = 800,
		x0 = -720,
		z0 = -1600,
		long = true
	}
}

local function dataOf(p: string)
	local v2 = v[p]
	assert(v2, "[GroundHeight] no height data for map " .. tostring(p))
	local v3 = p == "ironfield"
		and ""
		or require(MapSelect.module("GroundHeight", p))
	assert(#v3 == math.ceil(v2.nx * v2.nz * 2 / 3) * 4, "[GroundHeight] " .. p .. " height data has the wrong size")
	return v3, v2
end

local buf = buffer.create(156800)
local maxValue = 156800
local x0 = -560
local z0 = -560

for _, v2 in v do
	maxValue = math.max(maxValue, v2.nx * v2.nz * 2)
end

local buf2 = buffer.create(maxValue)

local v2 = {}

for i = 1, 64 do
	v2[string.byte("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", i)] = i - 1
end

local function decode(value: string, buf3: buffer)
	local total = 0

	for i = 1, #value, 4 do
		local v3, v4, v5, v6 = string.byte(value, i, i + 3)
		local v7 = v2[v3] * 262144 + v2[v4] * 4096 + (v2[v5] or 0) * 64 + (v2[v6] or 0)
		buffer.writeu8(buf3, total, v7 // 65536)

		if v5 ~= 61 then
			buffer.writeu8(buf3, total + 1, v7 // 256 % 256)
		end

		if v6 ~= 61 then
			buffer.writeu8(buf3, total + 2, v7 % 256)
		end

		total += 3
	end
end

local function offsetOf(data)
	local v3 = (data.x0 - x0) / 4
	local v4 = (data.z0 - z0) / 4
	local v5 = v3 % 1 == 0 and v4 % 1 == 0
	assert(v5, "[GroundHeight] a map's data must sit on the frame's columns")
	local v6 = data.long

	if not v6 then
		if v3 >= 0 and v4 >= 0 and v3 + data.nx <= 280 then
			v6 = v4 + data.nz <= 280
		else
			v6 = false
		end
	end

	assert(v6, "[GroundHeight] a map's data must sit inside the frame")

	return v3, v4
end

local function place(p)
	local v3, v4 = offsetOf(p)

	for i = 0, 279 do
		local v5 = math.clamp(i - v4, 0, p.nz - 1)

		for j = 0, 279 do
			local v6 = math.clamp(j - v3, 0, p.nx - 1)
			buffer.writeu16(buf, (i * 280 + j) * 2, (buffer.readu16(buf2, (v5 * p.nx + v6) * 2)))
		end
	end
end

local function column(value: number, value2: number) -- 11 equivalent calls inferred from this helper
	local v3 = math.clamp(value, 0, 279)
	local v4 = math.clamp(value2, 0, 279)
	return buffer.readu16(buf, (v4 * 280 + v3) * 2) / 100 - 40
end

local function setColumn(p: number, p2: number, p3: number) -- 2 equivalent calls inferred from this helper
	buffer.writeu16(buf, (p2 * 280 + p) * 2, (math.round((p3 + 40) * 100)))
end

local function level(p: number, p2: number, value: number, value2: number)
	for i = p, p2 do
		local v3 = column(i, value) -- inferred equivalent call
		local v4 = column(i, value2) -- inferred equivalent call

		for j = value + 1, value2 - 1 do
			local v5 = v3 + (v4 - v3) * (j - value) / (value2 - value)

			if column(i, j) < v5 then -- inferred equivalent call
				setColumn(i, j, v5) -- inferred equivalent call
			end
		end
	end
end

local GroundHeight = {}

local function base(p: number, p2: number)
	local v3 = (p - x0) / 4 - 0.5
	local v4 = (p2 - z0) / 4 - 0.5
	local v5 = math.floor(v3)
	local v6 = math.floor(v4)
	local v7 = v3 - v5
	local v8 = v4 - v6
	local v9 = column(v5, v6) + (column(v5 + 1, v6) - column(v5, v6)) * v7 -- inferred equivalent call
	return v9 + (column(v5, v6 + 1) + (column(v5 + 1, v6 + 1) - column(v5, v6 + 1)) * v7 - v9) * v8 -- inferred equivalent call
end

GroundHeight.base = base

GroundHeight.TRENCH_HALF = 6
GroundHeight.TRENCH_DEPTH = 5.5
GroundHeight.TRENCH_W = 3.5

local v3 = {
	{ cz = 190, x0 = -136, x1 = -104 },
	{ cz = 190, x0 = -96, x1 = -36 },
	{ cz = 58, x0 = -64, x1 = 4 },
	{ cz = 74, x0 = 40, x1 = 80 }
}

function GroundHeight.rim(p, p2: number, p3: number)
	local v4 = base(p2, p.cz - 9)
	return v4 + (base(p2, p.cz + 9) - v4) * math.clamp((p3 - p.cz + 9) / 18, 0, 1)
end

local trenches = {}
local function makeTrenches(p: string)
	table.clear(trenches)

	for _, v4 in p ~= "ironfield" and {} or v3 do
		for _, v5 in { 1, -1 } do
			local v6 = {
				cz = v4.cz * v5,
				x0 = 0,
				x1 = 0,
				enemy = 0,
				floors = 0
			}
			local x0_2

			if v5 == 1 then
				x0_2 = v4.x0
			else
				x0_2 = -v4.x1
			end

			v6.x0 = x0_2
			local x1

			if v5 == 1 then
				x1 = v4.x1
			else
				x1 = -v4.x0
			end

			v6.x1 = x1
			v6.enemy = -v5
			v6.floors = {}

			for i = v6.x0 + 2, v6.x1, 4 do
				local TRENCH_W = GroundHeight.TRENCH_W
				local v7 = math.min(
					GroundHeight.rim(v6, i, v6.cz - TRENCH_W),
					GroundHeight.rim(v6, i, v6.cz + TRENCH_W)
				)
				table.insert(v6.floors, math.round((v7 - GroundHeight.TRENCH_DEPTH) * 2) / 2)
			end

			table.insert(trenches, v6)
		end
	end
end
GroundHeight.TRENCHES = trenches

function GroundHeight.trenchFloor(p, p2: number)
	return p.floors[math.clamp(math.floor((p2 - p.x0) / 4), 0, #p.floors - 1) + 1]
end

function GroundHeight.at(p: number, p2: number)
	for _, v4 in trenches do
		if v4.x0 < p and p < v4.x1 and math.abs(p2 - v4.cz) < GroundHeight.TRENCH_HALF then
			return GroundHeight.trenchFloor(v4, p) - 1
		end
	end

	return base(p, p2)
end

local VOXEL_SIZE = WorldConfig.VOXEL_SIZE
local v4 = WorldConfig.ORIGIN

local v5 = {}
local v6 = {}

local function cachedRow(p, p2: number, p3: number, p4: number)
	local v7 = p3 // 16
	local v8 = p4 // 16
	local v9 = (v7 + 65536) * 131072 + (v8 + 65536)
	local v10 = p[v9]

	if v10 == nil then
		v10 = buffer.create(512)
		buffer.fill(v10, 0, 128)
		p[v9] = v10
	end

	local v11 = (p3 - v7 * 16 + (p4 - v8 * 16) * 16) * 2
	local v12 = buffer.readi16(v10, v11)

	if v12 ~= -32640 then
		return v12
	end

	v12 = math.floor((GroundHeight.at(v4.X + (p3 + 0.5) * VOXEL_SIZE, v4.Z + (p4 + 0.5) * VOXEL_SIZE) + p2 - v4.Y) / VOXEL_SIZE)
	local v13 = v12 > -32000 and v12 < 32000
	assert(v13, "[GroundHeight] ground row out of range")
	buffer.writei16(v10, v11, v12)

	return v12
end

function GroundHeight.row(p: number, p2: number)
	return cachedRow(v5, 0, p, p2)
end

function GroundHeight.surface(vector3: Vector3, p: number, vector3_2: Vector3, callback)
	local v7 = math.floor((vector3.Y - vector3_2.Y) / p)
	local v8 = v7 + 3
	local v9 = v7 - 24
	return function(p2: number, p3: number)
		local row = GroundHeight.row(p2, p3)

		for i = v8, math.max(row + 1, v9), -1 do
			if callback(p2, i, p3) ~= 0 and callback(p2, i + 1, p3) == 0 then
				return i
			end
		end

		return if v9 <= row then row else v7
	end
end

GroundHeight.COVER_LIFT = 0.25
function GroundHeight.coverRow(p: number, p2: number)
	return cachedRow(v6, GroundHeight.COVER_LIFT, p, p2) - 1
end

local buf3 = buffer.create(156800)
local set = {}

GroundHeight.COL = 4
GroundHeight.NX = 280
GroundHeight.NZ = 280
GroundHeight.X0 = x0
GroundHeight.Z0 = z0

function GroundHeight.columnAt(p: number, p2: number)
	return math.floor((p - x0) / 4), (math.floor((p2 - z0) / 4))
end

function GroundHeight.columnCenter(p: number, p2: number)
	return x0 + (p + 0.5) * 4, z0 + (p2 + 0.5) * 4
end

function GroundHeight.columnHeight(value: number, value2: number)
	return column(value, value2) -- inferred equivalent call
end

function GroundHeight.loadedHeight(value: number, value2: number)
	local v7 = math.clamp(value, 0, 279)
	local v8 = math.clamp(value2, 0, 279)
	return buffer.readu16(buf3, (v8 * 280 + v7) * 2) / 100 - 40
end

local function dropRows(value: number, value2: number)
	local v7 = x0 + (value - 0.5) * 4
	local v8 = z0 + (value2 - 0.5) * 4
	local v9 = math.floor((v7 - v4.X) / VOXEL_SIZE)
	local v10 = math.floor((v7 + 8 - v4.X) / VOXEL_SIZE)
	local v11 = math.floor((v8 - v4.Z) / VOXEL_SIZE)
	local v12 = math.floor((v8 + 8 - v4.Z) / VOXEL_SIZE)

	for i = v11 // 16, v12 // 16 do
		for j = v9 // 16, v10 // 16 do
			v5[(j + 65536) * 131072 + (i + 65536)] = nil
			v6[(j + 65536) * 131072 + (i + 65536)] = nil
		end
	end
end

function GroundHeight.lower(value: number, value2: number, p: number)
	if not (value < 0 or value2 < 0 or value >= 280 or value2 >= 280) and not (column(value, value2) <= p) then -- inferred equivalent call
		setColumn(value, value2, p) -- inferred equivalent call
		set[value2 * 280 + value] = true
		dropRows(value, value2)
	end
end

function GroundHeight.restore()
	if next(set) == nil then
		return
	end

	buffer.copy(buf, 0, buf3)
	table.clear(set)
	table.clear(v5)
	table.clear(v6)
end

local v7 = nil

local function frameFor(p) -- 2 equivalent calls inferred from this helper
	local origin = WorldConfig.ORIGIN
	x0 = -560 + (not p.long and 0 or origin.X)
	z0 = -560 + (not p.long and 0 or origin.Z)
	local z0_2 = z0
	GroundHeight.X0 = x0
	GroundHeight.Z0 = z0_2
end

local function load(name: string)
	local v8, v9 = dataOf(name)
	decode(v8, buf2)
	v7 = v9
	frameFor(v9) -- inferred equivalent call
	place(v9)

	if name == "ironfield" then
		local v10, v11 = offsetOf(v9)
		level(v10 + 58, v10 + 86, v11 + 173, v11 + 178)
		level(v10 + v9.nx - 1 - 86, v10 + v9.nx - 1 - 58, v11 + v9.nz - 1 - 178, v11 + v9.nz - 1 - 173)
	end

	makeTrenches(name)
	buffer.copy(buf3, 0, buf)
	table.clear(set)
	table.clear(v5)
	table.clear(v6)
end
load(MapSelect.name)
MapSelect.onChange(load, 1)

WorldConfig.onOrigin(function(vector3: Vector3)
	v4 = vector3
	local v8 = v7

	if v8 and v8.long then
		frameFor(v8) -- inferred equivalent call
		place(v8)
		buffer.copy(buf3, 0, buf)
	end

	table.clear(set)
	table.clear(v5)
	table.clear(v6)
end)

return GroundHeight